"""Verify that the release bundle copies every authored native Codex source unchanged."""

from __future__ import annotations

import json
import re
import unittest
from pathlib import Path


REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
CATALOG_PATH = REPOSITORY_ROOT / "harnesses/codex/catalog.json"
NATIVE_ROOT = REPOSITORY_ROOT / "harnesses/codex/plugins"
ROLE_ROOT = REPOSITORY_ROOT / "harnesses/codex/agent-roles"
OUTPUT_ROOT = REPOSITORY_ROOT / "dist/codex/plugins"
DISCOVERY_MANIFEST = REPOSITORY_ROOT / ".agents/plugins/marketplace.json"
SOURCE_ROOT = REPOSITORY_ROOT / "plugins"
SEMVER = re.compile(r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$")
# Exact shared paths in runtime guidance declare load dependencies. Historical
# references should name the artifact without an exact path.
RUNTIME_REFERENCE = re.compile(r"shared/(?:schemas|references)/[A-Za-z0-9@._/-]+\.(?:json|md)")


def read_json(path: Path) -> dict[str, object]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise AssertionError(f"{path} must contain a JSON object")
    return value


class CodexNativeSourceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        catalog = read_json(CATALOG_PATH)
        entries = catalog["plugins"]
        if not isinstance(entries, list):
            raise AssertionError("Codex catalog plugins must be an array")
        cls.plugin_ids = [entry["id"] for entry in entries if isinstance(entry, dict) and isinstance(entry.get("id"), str)]

    def test_catalog_and_native_source_trees_have_exact_plugin_parity(self) -> None:
        native_ids = {path.name for path in NATIVE_ROOT.iterdir() if path.is_dir()}
        self.assertEqual(native_ids, set(self.plugin_ids))

    def test_root_discovery_manifest_points_at_the_generated_bundle(self) -> None:
        discovery = read_json(DISCOVERY_MANIFEST)
        self.assertEqual(discovery.get("name"), "wisp-plugins")
        self.assertEqual(discovery.get("interface"), {"displayName": "Wisp Plugins"})
        entries = discovery.get("plugins")
        self.assertIsInstance(entries, list)
        self.assertEqual([entry["name"] for entry in entries], self.plugin_ids)
        for entry in entries:
            self.assertEqual(entry["source"], {"source": "local", "path": f"./dist/codex/plugins/{entry['name']}"})

    def test_native_skill_sets_match_claude_source_skill_sets(self) -> None:
        for plugin_id in self.plugin_ids:
            source_skills = {path.name for path in (SOURCE_ROOT / plugin_id / "skills").iterdir() if (path / "SKILL.md").is_file()}
            native_skills = {path.name for path in (NATIVE_ROOT / plugin_id / "skills").iterdir() if (path / "SKILL.md").is_file()}
            self.assertEqual(native_skills, source_skills, plugin_id)

    def test_native_manifests_and_skill_frontmatter_meet_the_release_contract(self) -> None:
        for plugin_id in self.plugin_ids:
            manifest = read_json(NATIVE_ROOT / plugin_id / ".codex-plugin" / "plugin.json")
            self.assertEqual(manifest.get("name"), plugin_id)
            self.assertRegex(str(manifest.get("version", "")), SEMVER)
            self.assertTrue(isinstance(manifest.get("description"), str) and manifest["description"].strip())
            self.assertEqual(manifest.get("skills"), "./skills/")
            author = manifest.get("author")
            self.assertTrue(isinstance(author, dict) and isinstance(author.get("name"), str) and author["name"].strip(), plugin_id)
            interface = manifest.get("interface")
            self.assertIsInstance(interface, dict, plugin_id)
            for field in ("displayName", "shortDescription", "longDescription", "developerName", "category"):
                self.assertTrue(isinstance(interface.get(field), str) and interface[field].strip(), f"{plugin_id}.{field}")
            for field in ("capabilities", "defaultPrompt"):
                self.assertTrue(isinstance(interface.get(field), list) and all(isinstance(item, str) and item.strip() for item in interface[field]), f"{plugin_id}.{field}")
            for skill in (NATIVE_ROOT / plugin_id / "skills").iterdir():
                contents = (skill / "SKILL.md").read_text(encoding="utf-8")
                self.assertTrue(contents.startswith("---\n"), f"{plugin_id}/{skill.name}")
                frontmatter, _, _ = contents[4:].partition("\n---\n")
                self.assertRegex(frontmatter, rf"(?m)^name: {re.escape(skill.name)}$")
                self.assertRegex(frontmatter, r"(?m)^description: .+\S$")

    def test_each_native_runtime_reference_is_declared_for_materialization(self) -> None:
        catalog = read_json(CATALOG_PATH)
        global_runtime = catalog.get("runtime_files")
        self.assertIsInstance(global_runtime, list)
        entries = {entry["id"]: entry for entry in catalog["plugins"] if isinstance(entry, dict) and isinstance(entry.get("id"), str)}
        for plugin_id in self.plugin_ids:
            entry = entries[plugin_id]
            runtime = [*global_runtime, *entry.get("runtime_files", [])]
            declared_sources = {
                item if isinstance(item, str) else item.get("source")
                for item in runtime
                if isinstance(item, str) or isinstance(item, dict)
            }
            expected = {
                match.rstrip(".,;:)")
                for skill in (NATIVE_ROOT / plugin_id / "skills").iterdir()
                for match in RUNTIME_REFERENCE.findall((skill / "SKILL.md").read_text(encoding="utf-8"))
            }
            pending = list(expected)
            while pending:
                reference = pending.pop()
                source = REPOSITORY_ROOT / reference
                if not source.is_file() or not reference.startswith("shared/references/"):
                    continue
                for nested in RUNTIME_REFERENCE.findall(source.read_text(encoding="utf-8")):
                    nested = nested.rstrip(".,;:)")
                    if nested not in expected:
                        expected.add(nested)
                        pending.append(nested)
            if "shared/schemas" in declared_sources:
                expected = {reference for reference in expected if not reference.startswith("shared/schemas/")}
            actual = {source for source in declared_sources if isinstance(source, str)}
            self.assertTrue(expected <= actual, f"{plugin_id} does not materialize {sorted(expected - actual)}")

    def test_delegating_skills_select_packaged_role_cards(self) -> None:
        role_files = {path.name: path.read_bytes() for path in ROLE_ROOT.glob("*.md")}
        self.assertIn("README.md", role_files)
        role_guide = role_files["README.md"].decode("utf-8")
        for field in ("Role", "Objective", "Inputs", "Owned paths", "Exclusions", "Output", "Evidence", "Completion"):
            self.assertIn(f"| {field} |", role_guide)
        for plugin_id in self.plugin_ids:
            for name, contents in role_files.items():
                output = OUTPUT_ROOT / plugin_id / "agent-roles" / name
                self.assertTrue(output.is_file(), f"{plugin_id} is missing agent role {name}")
                self.assertEqual(output.read_bytes(), contents, f"{plugin_id} rewrote agent role {name}")
            for skill in (NATIVE_ROOT / plugin_id / "skills").iterdir():
                contents = (skill / "SKILL.md").read_text(encoding="utf-8")
                can_delegate = any(
                    phrase in contents
                    for phrase in ("teams are available", "teams are enabled", "teams may", "teammates may")
                )
                if can_delegate:
                    self.assertIn("agent-roles/README.md", contents, f"{plugin_id}/{skill.name} can delegate without a role card")

    def test_mason_materializes_the_cross_harness_authoring_guide(self) -> None:
        source = REPOSITORY_ROOT / "shared/harness-authoring.md"
        output = OUTPUT_ROOT / "mason/shared/harness-authoring.md"
        self.assertTrue(output.is_file())
        self.assertEqual(output.read_bytes(), source.read_bytes())

    def test_every_authored_native_file_is_identical_in_the_release_bundle(self) -> None:
        for plugin_id in self.plugin_ids:
            source_root = NATIVE_ROOT / plugin_id
            output_root = OUTPUT_ROOT / plugin_id
            for source in source_root.rglob("*"):
                if not source.is_file():
                    continue
                output = output_root / source.relative_to(source_root)
                self.assertTrue(output.is_file(), f"{plugin_id} is missing {source.relative_to(source_root)}")
                self.assertFalse(output.is_symlink(), f"{plugin_id} ships {source.relative_to(source_root)} as a symlink")
                self.assertEqual(output.read_bytes(), source.read_bytes(), f"{plugin_id} rewrote {source.relative_to(source_root)}")


if __name__ == "__main__":
    unittest.main()

"""Enforce concern-first shared references, valid paths, and runtime callers."""

from __future__ import annotations

import re
import unittest
from pathlib import Path
from urllib.parse import unquote


REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
REFERENCE_ROOT = REPOSITORY_ROOT / "shared/references"
REFERENCE_PATH = re.compile(r"shared/references/[A-Za-z0-9@._/-]+\.md")
SCHEMA_PATH = re.compile(r"shared/schemas/[A-Za-z0-9@._/-]+\.json")
MARKDOWN_LINK = re.compile(r"!?\[[^\]]*\]\(([^)]+)\)")
REFERENCE_LINK = re.compile(r"^\s*\[[^\]]+\]:\s+(\S+)", re.MULTILINE)
HTML_LINK = re.compile(r"(?:href|src)=[\"']([^\"']+)[\"']")
RETIRED_REFERENCE_NAME = re.compile(
    r"(?:\*|rust|typescript|python|go)-hazards(?:-t7-t10)?\.md|(?<!/)changesets\.md"
)
TEXT_SUFFIXES = {".json", ".md", ".py", ".sh", ".yaml", ".yml"}
EXCLUDED_PARTS = {".git", ".agents", "dist", "node_modules"}
AUTHORING_ONLY = {
    "shared/references/README.md",
    "shared/references/authoring/diagrams.md",
    "shared/references/tooling/cli.md",
}
CONCERN_DIRECTORIES = {
    "architecture",
    "authoring",
    "delivery",
    "evaluation",
    "hazards",
    "tooling",
    "verification",
    "workspace",
}
# Published schemas are byte-immutable. Keep narrow exceptions for exact paths
# embedded before a reference move; live skill and agent routes must still use
# current paths and pass the checks below.
IMMUTABLE_PATH_EXCEPTIONS = {
    (
        "shared/schemas/changeset@2.json",
        "shared/references/" "changesets" ".md",
    ): "shared/references/delivery/changesets.md",
}


def authored_text_files() -> list[Path]:
    return [
        path
        for path in REPOSITORY_ROOT.rglob("*")
        if path.is_file()
        and path.suffix in TEXT_SUFFIXES
        and path.name != "CHANGELOG.md"
        and not EXCLUDED_PARTS.intersection(path.relative_to(REPOSITORY_ROOT).parts)
    ]


def is_runtime_caller(path: Path) -> bool:
    relative = path.relative_to(REPOSITORY_ROOT)
    parts = relative.parts
    if parts[:2] == ("shared", "references"):
        return path != REFERENCE_ROOT / "README.md"
    if parts[:2] == ("shared", "hooks"):
        return True
    if parts and parts[0] == "plugins":
        return "agents" in parts or "skills" in parts
    return parts[:3] == ("harnesses", "codex", "plugins") and "skills" in parts


def local_markdown_target(raw_target: str) -> str | None:
    target = raw_target.strip()
    if target.startswith("<") and ">" in target:
        target = target[1 : target.index(">")]
    else:
        target = target.split(maxsplit=1)[0]
    if not target or target.startswith("#") or "://" in target or target.startswith("mailto:"):
        return None
    return unquote(target.split("#", 1)[0].split("?", 1)[0])


class ReferenceIntegrityTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.sources = {
            path: path.read_text(encoding="utf-8")
            for path in authored_text_files()
        }

    def test_exact_reference_paths_exist(self) -> None:
        broken: list[str] = []
        for source, contents in self.sources.items():
            for reference in REFERENCE_PATH.findall(contents):
                source_name = source.relative_to(REPOSITORY_ROOT).as_posix()
                if (source_name, reference) in IMMUTABLE_PATH_EXCEPTIONS:
                    continue
                if not (REPOSITORY_ROOT / reference).is_file():
                    broken.append(f"{source_name} -> {reference}")
        self.assertEqual(broken, [])

    def test_exact_schema_paths_exist(self) -> None:
        broken = [
            f"{source.relative_to(REPOSITORY_ROOT).as_posix()} -> {schema}"
            for source, contents in self.sources.items()
            if source.suffix in {".json", ".md", ".yaml", ".yml"}
            for schema in SCHEMA_PATH.findall(contents)
            if not (REPOSITORY_ROOT / schema).is_file()
        ]
        self.assertEqual(broken, [])

    def test_immutable_path_exceptions_have_live_replacements(self) -> None:
        invalid: list[str] = []
        for (source_name, historical), replacement in IMMUTABLE_PATH_EXCEPTIONS.items():
            source = REPOSITORY_ROOT / source_name
            if historical not in source.read_text(encoding="utf-8"):
                invalid.append(f"{source_name} no longer contains {historical}")
            if not (REPOSITORY_ROOT / replacement).is_file():
                invalid.append(f"replacement missing: {replacement}")
            live_callers = [
                path.relative_to(REPOSITORY_ROOT).as_posix()
                for path, contents in self.sources.items()
                if path != source and is_runtime_caller(path) and historical in contents
            ]
            if live_callers:
                invalid.append(f"live callers still use {historical}: {live_callers}")
        self.assertEqual(invalid, [])

    def test_local_markdown_links_resolve(self) -> None:
        broken: list[str] = []
        for source, contents in self.sources.items():
            if source.suffix != ".md":
                continue
            raw_targets = (
                MARKDOWN_LINK.findall(contents)
                + REFERENCE_LINK.findall(contents)
                + HTML_LINK.findall(contents)
            )
            for raw_target in raw_targets:
                target = local_markdown_target(raw_target)
                if target is None:
                    continue
                resolved = (source.parent / target).resolve()
                if not resolved.exists():
                    source_name = source.relative_to(REPOSITORY_ROOT).as_posix()
                    broken.append(f"{source_name} -> {target}")
        self.assertEqual(broken, [])

    def test_retired_or_ambiguous_reference_names_are_absent(self) -> None:
        stale = [
            f"{source.relative_to(REPOSITORY_ROOT).as_posix()} -> {match.group(0)}"
            for source, contents in self.sources.items()
            for match in RETIRED_REFERENCE_NAME.finditer(contents)
        ]
        self.assertEqual(stale, [])

    def test_reference_paths_are_concern_first(self) -> None:
        misplaced = [
            path.relative_to(REFERENCE_ROOT).as_posix()
            for path in REFERENCE_ROOT.rglob("*.md")
            if path != REFERENCE_ROOT / "README.md"
            and path.relative_to(REFERENCE_ROOT).parts[0] not in CONCERN_DIRECTORIES
        ]
        self.assertEqual(misplaced, [])

    def test_each_runtime_reference_has_a_runtime_caller(self) -> None:
        missing: list[str] = []
        for reference_file in REFERENCE_ROOT.rglob("*.md"):
            reference = reference_file.relative_to(REPOSITORY_ROOT).as_posix()
            if reference in AUTHORING_ONLY:
                continue
            callers = [
                source
                for source, contents in self.sources.items()
                if source != reference_file and is_runtime_caller(source) and reference in contents
            ]
            if not callers:
                missing.append(reference)
        self.assertEqual(missing, [])

    def test_adr_index_matches_records(self) -> None:
        index = REPOSITORY_ROOT / "docs/adr/README.md"
        rows: dict[str, list[str]] = {}
        problems: list[str] = []
        for line in index.read_text(encoding="utf-8").splitlines():
            if not line.startswith("| ["):
                continue
            cells = [cell.strip() for cell in line.strip("|").split("|")]
            if len(cells) != 5 or not cells[4].startswith("Do not "):
                problems.append(f"malformed row: {line[:40]}")
                continue
            rows[cells[0][1:4]] = cells
        records = {record.name[:3]: record for record in index.parent.glob("[0-9][0-9][0-9]-*.md")}
        self.assertEqual(sorted(rows), sorted(records))
        for number, record in records.items():
            _, status, _, relation, _ = rows[number]
            meta = [
                line
                for line in record.read_text(encoding="utf-8").splitlines()
                if re.match(r"\*\*(Status|Supersedes|Extended by):\*\*", line)
            ]
            superseded = any("superseded" in line.lower() for line in meta if line.startswith("**Status:"))
            if status not in {"Accepted", "Partially superseded", "Superseded"} or superseded == (status == "Accepted"):
                problems.append(f"{number}: index status {status!r} disagrees with the record")
            for other in re.findall(r"ADR-(\d{3})", " ".join(meta)):
                if other not in rows or other not in relation:
                    problems.append(f"{number}: Relation omits or misnames {other}")
        self.assertEqual(problems, [])


if __name__ == "__main__":
    unittest.main()

#!/usr/bin/env python3
"""Block commits that violate generated-output or schema-version invariants."""

from __future__ import annotations

import json
import re
import subprocess
import sys
from pathlib import Path
from typing import Any


COMMIT_COMMAND = re.compile(r"(?:^|[;&|]\s*)git(?:\s+-[A-Za-z]\s+[^\s;&|]+)*\s+commit(?:\s|$)")
REPOSITORY_MARKERS = ("marketplace.json", "shared/constitution.md", "tools/build-codex-marketplace.py")


def emit_block(reason: str) -> None:
    print(json.dumps({"decision": "block", "reason": reason}))


def repository_root(cwd: str) -> Path | None:
    try:
        result = subprocess.run(
            ["git", "-C", cwd, "rev-parse", "--show-toplevel"],
            check=True,
            capture_output=True,
            text=True,
        )
    except (OSError, subprocess.CalledProcessError):
        return None
    root = Path(result.stdout.strip())
    if all((root / marker).is_file() for marker in REPOSITORY_MARKERS):
        return root
    return None


def is_commit_command(command: str) -> bool:
    return bool(COMMIT_COMMAND.search(command))


def staged_schema_mutations(root: Path) -> list[str]:
    result = subprocess.run(
        ["git", "-C", str(root), "diff", "--cached", "--name-status", "--", "shared/schemas"],
        check=True,
        capture_output=True,
        text=True,
    )
    return [line for line in result.stdout.splitlines() if line and not line.startswith("A\t")]


def generated_bundle_is_current(root: Path) -> bool:
    result = subprocess.run(
        [sys.executable, "tools/build-codex-marketplace.py", "--check"],
        cwd=root,
        capture_output=True,
        text=True,
    )
    return result.returncode == 0


def evaluate(payload: dict[str, Any]) -> str | None:
    tool_name = payload.get("tool_name")
    tool_input = payload.get("tool_input")
    if tool_name != "Bash" or not isinstance(tool_input, dict):
        return None
    command = tool_input.get("command")
    cwd = payload.get("cwd")
    if not isinstance(command, str) or not is_commit_command(command) or not isinstance(cwd, str):
        return None
    root = repository_root(cwd)
    if root is None:
        return None
    mutations = staged_schema_mutations(root)
    if mutations:
        changed = ", ".join(mutations)
        return f"Tracked schema versions are immutable. Add a new shared/schemas/<name>@<N+1>.json instead of committing: {changed}"
    if not generated_bundle_is_current(root):
        return "The generated Codex marketplace is stale. Run python3 tools/build-codex-marketplace.py, review dist/codex, then commit."
    return None


def main() -> int:
    try:
        payload = json.load(sys.stdin)
    except json.JSONDecodeError:
        return 0
    if not isinstance(payload, dict):
        return 0
    reason = evaluate(payload)
    if reason:
        emit_block(reason)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

