74	    failures += 1;
75	    const message = error instanceof Error ? error.message : String(error);
76	    console.error(`FAIL: ${block.file}:${block.startLine} (block ${index + 1}): ${message}`);
77	  }
78	}
79	
80	if (failures > 0) {
81	  console.error(
82	    `FAILED: ${failures} of ${blocks.length} mermaid block(s) did not parse. Fix and re-run.`,
83	  );
84	  process.exitCode = 1;
85	} else {
86	  console.log(`OK: ${blocks.length} mermaid block(s) parse successfully.`);
87	}
